-- Speglar det som lades på databasen 2026-09-15 via apply_migration i fem delar:
--   cj2_order_code_from_catalogue_part_01  (backup, schema, familj, parametrar)
--   cj2_order_code_from_catalogue_part_02  (värdelista)
--   cj2_order_code_from_catalogue_part_03  (regler 1–20)
--   cj2_order_code_from_catalogue_part_04  (regler 21–40)
--   cj2_order_code_from_catalogue_part_05  (regler 41–53, dokumentkarta, produktspecar)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts cj2):
--   regler  53   md5 83e474c3d15145968c855475c3ffa4c9   villkor 4b808a9bbf8ca253929afc32ebbea272
--   värden  75   md5 94589b52b6024f911aa943dd56f2019f
--   schema       md5 8115fa34dea9edad657eddf78efde6f4
-- Verifierat live: /sv/configurator/cj2 bygger CDJ2D16-60Z-NW-M9BW-B (katalogens
-- beställningsexempel, sida 75) och stoppar axiell port R med fäste D.
--
-- CJ2: beställnyckeln enligt SMC Air Cylinder CJ2 Series.
-- GENERERAD ur src/lib/catalog/cj2.ts -- redigera inte för hand.
--
-- Rättar familjen cj2, som hade mallen 'CJ2-{bore_mm}-{stroke_mm}-{cushioning}{sensing}'.
-- SMC:s kod är C{magnet}J2{fäste}{ø}-{slag}{dämpning}{port}Z-{pivot}{kolvstångsände}-{givare}{kabel}{antal}-{givarfäste}-{special},
-- t.ex. CDJ2D16-60Z-NW-M9BW-B (sida 75). Fäste, port, pivotfäste,
-- kolvstångstillbehör och givarfäste fanns inte alls.
--
-- SMC-CJ2B20 finns inte (CJ2 slutar vid ø16) och avaktiveras. SMC-CJ2,
-- SMC-CJ2B10 och SMC-CJ2B16 får katalogens borrningar, slag, tryck och
-- temperatur.

begin;

create schema if not exists backup;
create table if not exists backup.cj2_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'cj2'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'cj2'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'cj2';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-CJ2-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"6","label":"ø6 mm"},{"v":"10","label":"ø10 mm"},{"v":"16","label":"ø16 mm"}]},{"id":"mounting","step":2,"title_sv":"Fäste","title_en":"Mounting","required":true,"type":"single_select","options":[{"v":"B","label":"Basutförande"},{"v":"E","label":"Dubbelsidig gänghals (double-side bossed)"},{"v":"D","label":"Dubbelt gaffelfäste (ø10, ø16)"},{"v":"L","label":"Enkelt fotfäste"},{"v":"M","label":"Dubbelt fotfäste"},{"v":"F","label":"Fläns vid kolvstången"},{"v":"G","label":"Fläns vid gaveln"}]},{"id":"stroke_mm","step":3,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":1,"max":400,"unit":"mm"},{"id":"magnet","step":4,"title_sv":"Inbyggd magnet","title_en":"Built-in magnet","required":false,"type":"single_select","options":[{"v":"D","label":"Inbyggd magnet för givare (CDJ2)"}]},{"id":"cushion","step":5,"title_sv":"Dämpning","title_en":"Cushion","required":false,"type":"single_select","options":[{"v":"A","label":"Luftdämpning (ø10, ø16)"}]},{"id":"port","step":6,"title_sv":"Portens läge i gaveln","title_en":"Head cover port location","required":false,"type":"single_select","options":[{"v":"R","label":"Axiell port i gaveln (ej fäste D och E)"}]},{"id":"pivot","step":7,"title_sv":"Pivotfäste","title_en":"Pivot bracket","required":false,"type":"single_select","options":[{"v":"N","label":"Pivotfäste (T-fäste) medlevererat, bara fäste D"}]},{"id":"rod_end","step":8,"title_sv":"Kolvstångstillbehör","title_en":"Rod end bracket","required":false,"type":"single_select","options":[{"v":"V","label":"Enkel knäled (ø10, ø16)"},{"v":"W","label":"Dubbel knäled (ø10, ø16)"},{"v":"T","label":"Kolvstångskåpa, platt"},{"v":"U","label":"Kolvstångskåpa, rund"}]},{"id":"switch_mount","step":9,"title_sv":"Givarfäste","title_en":"Auto switch mounting type","required":false,"type":"single_select","options":[{"v":"A","label":"Givarfäste för skena (ø10, ø16)"},{"v":"B","label":"Givarfäste för band"}]},{"id":"switch","step":10,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN, rak"},{"v":"M9P","label":"D-M9P, 3-tråd PNP, rak"},{"v":"M9B","label":"D-M9B, 2-tråd, rak"},{"v":"M9NV","label":"D-M9NV, 3-tråd NPN, vinklad"},{"v":"M9PV","label":"D-M9PV, 3-tråd PNP, vinklad"},{"v":"M9BV","label":"D-M9BV, 2-tråd, vinklad"},{"v":"H7C","label":"D-H7C, 2-tråd, kontakt (band)"},{"v":"J79C","label":"D-J79C, 2-tråd, kontakt (skena)"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering, rak"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering, rak"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering, rak"},{"v":"M9NWV","label":"D-M9NWV, NPN, tvåfärgsindikering, vinklad"},{"v":"M9PWV","label":"D-M9PWV, PNP, tvåfärgsindikering, vinklad"},{"v":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinklad"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät, rak"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät, rak"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak"},{"v":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad"},{"v":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad"},{"v":"H7NF","label":"D-H7NF, 4-tråd NPN, diagnostikutgång (band)"},{"v":"F79F","label":"D-F79F, 4-tråd NPN, diagnostikutgång (skena)"},{"v":"A96","label":"D-A96, reed 3-tråd, rak"},{"v":"A96V","label":"D-A96V, reed 3-tråd, vinklad"},{"v":"A72","label":"D-A72, reed 200 V, vinklad (skena)"},{"v":"A72H","label":"D-A72H, reed 200 V, rak (skena)"},{"v":"A93","label":"D-A93, reed 2-tråd, rak"},{"v":"A93V","label":"D-A93V, reed 2-tråd, vinklad"},{"v":"A90","label":"D-A90, reed utan indikering, rak"},{"v":"A90V","label":"D-A90V, reed utan indikering, vinklad"},{"v":"C73C","label":"D-C73C, reed kontakt (band)"},{"v":"A73C","label":"D-A73C, reed kontakt (skena)"},{"v":"C80C","label":"D-C80C, reed kontakt utan indikering (band)"},{"v":"A80C","label":"D-A80C, reed kontakt utan indikering (skena)"},{"v":"A79W","label":"D-A79W, reed tvåfärgsindikering (skena)"}]},{"id":"lead","step":11,"title_sv":"Givarens kabellängd","title_en":"Lead wire length","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"},{"v":"N","label":"Utan kabel (kontaktgivare)"}]},{"id":"count","step":12,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"1 givare (standard är 2)"}]},{"id":"mto","step":13,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"XA","label":"-XA□ Ändrad kolvstångsände (XA-nummer anges vid beställning)"},{"v":"XB6","label":"-XB6 Värmebeständig –10…150 °C (utan givare och luftdämpning)"},{"v":"XB7","label":"-XB7 Köldbeständig –40…70 °C (utan givare och luftdämpning)"},{"v":"XB9","label":"-XB9 Låg hastighet 10–50 mm/s (utan luftdämpning)"},{"v":"XB13","label":"-XB13 Låg hastighet 5–50 mm/s (ø6, utan luftdämpning)"},{"v":"XC3","label":"-XC3 Speciell portplacering (utan luftdämpning; givare bara på band)"},{"v":"XC8","label":"-XC8 Justerbart slag, plus-sidan (ø10, ø16, utan luftdämpning)"},{"v":"XC9","label":"-XC9 Justerbart slag, minus-sidan (ø10, ø16, utan luftdämpning)"},{"v":"XC10","label":"-XC10 Dubbelslag, dubbel kolvstång (ø10, ø16, utan luftdämpning)"},{"v":"XC11","label":"-XC11 Dubbelslag, enkel kolvstång (ø10, ø16, utan luftdämpning)"},{"v":"XC22","label":"-XC22 Fluorgummitätningar (utan luftdämpning)"},{"v":"XC51","label":"-XC51 Med slangnippel"},{"v":"XC85","label":"-XC85 Fett för livsmedelsindustrin"},{"v":"X446","label":"-X446 PTFE-fett (ø10, ø16)"},{"v":"X2838","label":"-X2838 Dubbelt gaffelfäste med snabbsprint och T-fäste (fäste D, ø10/16, utan luftdämpning, givare bara på band)"}]}]}'::jsonb,
        'SMC CJ2 rund minicylinder', 'SMC CJ2 round mini cylinder', 'cylinder')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Rund minicylinder ø6–16, dubbelverkande enkel kolvstång',
  description = 'SMC CJ2 round mini air cylinder, double acting single rod, ø6/10/16 mm, standard strokes 15–200 mm.',
  stroke_min_mm = 1,
  stroke_max_mm = 400,
  order_code_template = 'C{magnet}J2{mounting}{bore}-{stroke_mm}{cushion}{port}Z-{pivot}{rod_end}-{switch}{lead}{count}-{switch_mount}-{mto}',
  rules_schema_id = 'SCHEMA-CJ2-V1'
where slug = 'cj2';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'cj2';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'cj2';

