     jsonb_to_recordset('[{"param_key":"bore","label":"Kolvdiameter","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"mounting","label":"Fäste","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"stroke_mm","label":"Slaglängd","param_type":"number","sort_order":3,"required":true,"min_value":1,"max_value":400},{"param_key":"magnet","label":"Inbyggd magnet","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"cushion","label":"Dämpning","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"port","label":"Portens läge i gaveln","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"pivot","label":"Pivotfäste","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"rod_end","label":"Kolvstångstillbehör","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"switch_mount","label":"Givarfäste","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"switch","label":"Magnetgivare","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Givarens kabellängd","param_type":"select","sort_order":11,"required":false,"min_value":null,"max_value":null},{"param_key":"count","label":"Antal givare","param_type":"select","sort_order":12,"required":false,"min_value":null,"max_value":null},{"param_key":"mto","label":"Specialutförande","param_type":"select","sort_order":13,"required":false,"min_value":null,"max_value":null}]'::jsonb)
