from jsonb_array_elements('[{"severity":"warn","if_json":{"and":[{"==":[{"var":"switch_mount"},"A"]},{"in":[{"var":"switch"},["A96V","A72","A72H","A93V","A90V","A73C","A80C"]]},{"!=":[{"var":"count"},"S"]},{">":[{"var":"stroke_mm"},0]},{"<":[{"var":"stroke_mm"},10]}]},"message_sv":"Minsta slag för två givare D-A96V/A72/A72H/A93V/A90V/A73C/A80C på skena är 10 mm (sida 177). Välj en givare eller längre slag.","message_en":"The minimum stroke for two D-A96V/A72/A72H/A93V/A90V/A73C/A80C switches on rail is 10 mm (page 177). Choose one switch or a longer stroke.","goto_step":"cj2-stroke_mm"},{"severity":"error","if_json":{"and":[{"in":[{"var":"mto"},["XB6","XB7","XB9","XB13","XC3","XC8","XC9","XC10","XC11","XC22","X2838"]]},{"==":[{"var":"cushion"},"A"]}]},"message_sv":"-XB6, XB7, XB9, XB13, XC3, XC8, XC9, XC10, XC11, XC22 och X2838 finns inte med luftdämpning (sida 72, not 4).","message_en":"-XB6, XB7, XB9, XB13, XC3, XC8, XC9, XC10, XC11, XC22 and X2838 are not available with air cushion (page 72, note 4).","goto_step":"cj2-mto"},{"severity":"error","if_json":{"and":[{"in":[{"var":"mto"},["XB6","XB7"]]},{"!=":[{"var":"switch"},""]}]},"message_sv":"-XB6 och XB7 finns inte med givare (sida 72, not 3).","message_en":"-XB6 and XB7 are not available with an auto switch (page 72, note 3).","goto_step":"cj2-mto"},{"severity":"error","if_json":{"and":[{"in":[{"var":"mto"},["XC3","X2838"]]},{"==":[{"var":"switch_mount"},"A"]}]},"message_sv":"Med -XC3 och X2838 monteras givare bara med band (B), inte på skena (sida 72, not 2 och 11).","message_en":"With -XC3 and X2838 auto switches are band-mounted (B) only, not rail-mounted (page 72, notes 2 and 11).","goto_step":"cj2-mto"},{"severity":"error","if_json":{"and":[{"in":[{"var":"mto"},["XB13"]]},{"in":[{"var":"bore"},["10","16"]]}]},"message_sv":"-XB13 finns för ø6 (sida 72).","message_en":"-XB13 exist for ø6 (page 72).","goto_step":"cj2-mto"},{"severity":"error","if_json":{"and":[{"in":[{"var":"mto"},["XC8","XC9","XC10","XC11","X446","X2838"]]},{"in":[{"var":"bore"},["6"]]}]},"message_sv":"-XC8, XC9, XC10, XC11, X446 och X2838 finns för ø10 och 16 (sida 72).","message_en":"-XC8, XC9, XC10, XC11, X446 and X2838 exist for ø10 and 16 (page 72).","goto_step":"cj2-mto"},{"severity":"error","if_json":{"and":[{"==":[{"var":"mto"},"X2838"]},{"!=":[{"var":"mounting"},"D"]},{"!=":[{"var":"mounting"},""]}]},"message_sv":"-X2838 är det dubbla gaffelfästet med snabbsprint — kräver fäste D (sida 182).","message_en":"-X2838 is the double clevis with one-touch connecting pin — needs mounting D (page 182).","goto_step":"cj2-mto"},{"severity":"info","if_json":{"==":[{"var":"bore"},"6"]},"message_sv":"ø6: cirka 14 N plus-sidan vid 0,5 MPa (kolvarea × tryck); minsta tryck 0,12 MPa; max 0,7 MPa; standardslag 15, 30, 45 och 60 mm, tillverkas upp till 200 mm (sida 75).","message_en":"ø6: about 14 N extending at 0.5 MPa (piston area × pressure); minimum pressure 0.12 MPa; max 0.7 MPa; standard strokes 15, 30, 45 and 60 mm, manufactured up to 200 mm (page 75).","goto_step":"cj2-bore"},{"severity":"info","if_json":{"==":[{"var":"bore"},"10"]},"message_sv":"ø10: cirka 39 N plus-sidan vid 0,5 MPa (kolvarea × tryck); minsta tryck 0,06 MPa (0,1 MPa med luftdämpning); max 0,7 MPa; standardslag 15, 30, 45, 60, 75, 100, 125 och 150 mm, tillverkas upp till 400 mm (sida 75).","message_en":"ø10: about 39 N extending at 0.5 MPa (piston area × pressure); minimum pressure 0.06 MPa (0.1 MPa with air cushion); max 0.7 MPa; standard strokes 15, 30, 45, 60, 75, 100, 125 and 150 mm, manufactured up to 400 mm (page 75).","goto_step":"cj2-bore"},{"severity":"info","if_json":{"==":[{"var":"bore"},"16"]},"message_sv":"ø16: cirka 101 N plus-sidan vid 0,5 MPa (kolvarea × tryck); minsta tryck 0,06 MPa (0,1 MPa med luftdämpning); max 0,7 MPa; standardslag 15, 30, 45, 60, 75, 100, 125, 150, 175 och 200 mm, tillverkas upp till 400 mm (sida 75).","message_en":"ø16: about 101 N extending at 0.5 MPa (piston area × pressure); minimum pressure 0.06 MPa (0.1 MPa with air cushion); max 0.7 MPa; standard strokes 15, 30, 45, 60, 75, 100, 125, 150, 175 and 200 mm, manufactured up to 400 mm (page 75).","goto_step":"cj2-bore"},{"severity":"info","if_json":{"!=":[{"var":"switch"},""]},"message_sv":"Med givare är temperaturområdet -10…60 °C (utan: -10…70 °C). Givaren levereras löst; bandfästet är förmonterat (sida 74).","message_en":"With auto switch the temperature range is -10…60 °C (without: -10…70 °C). The switch ships loose; the band bracket is pre-assembled (page 74).","goto_step":"cj2-switch"},{"severity":"info","if_json":{"or":[{"in":[{"var":"mounting"},["L","M","F","G"]]},{"!=":[{"var":"pivot"},""]},{"!=":[{"var":"rod_end"},""]}]},"message_sv":"Fot-/flänsfäste, pivotfäste och kolvstångstillbehör levereras löst tillsammans med cylindern, inte monterade (sida 74).","message_en":"Foot/flange brackets, pivot bracket and rod end accessories ship loose together with the cylinder, not assembled (page 74).","goto_step":"cj2-mounting"},{"severity":"info","if_json":{"==":[{"var":"cushion"},"A"]},"message_sv":"Med luftdämpning är kolvhastigheten 50–1000 mm/s (gummidämpning 50–750 mm/s) (sida 75).","message_en":"With air cushion the piston speed is 50–1000 mm/s (rubber bumper 50–750 mm/s) (page 75).","goto_step":"cj2-cushion"}]'::jsonb) r;

insert into knowledge_doc_families (source_file, family_slug, doc_title)
values ('smc-kat-cj2.pdf', 'cj2', 'SMC — SMC Air Cylinder CJ2 Series')
on conflict (source_file, family_slug) do update set doc_title = excluded.doc_title;


update product_specs s set value = '150 mm (standard); tillverkas upp till 400 mm'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2B10' and s.key = 'stroke_mm';

update product_specs s set value = '-10…+70 (utan givare), -10…+60 (med givare)'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2B10' and s.key = 'temp_range';

update product_specs s set value = '7'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2B10' and s.key = 'max_pressure';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('standard_strokes_mm', '15, 30, 45, 60, 75, 100, 125, 150'),
  ('min_pressure_mpa', '0.06'),
  ('order_code_example', 'CJ2B10-150Z'),
  ('catalogue', 'SMC CJ2-Z, How to Order sida 74, data sida 75')
) as x(key, value)
where p.sku = 'SMC-CJ2B10'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);


update product_specs s set value = '200 mm (standard); tillverkas upp till 400 mm'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2B16' and s.key = 'stroke_mm';

update product_specs s set value = '-10…+70 (utan givare), -10…+60 (med givare)'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2B16' and s.key = 'temp_range';

update product_specs s set value = '7'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2B16' and s.key = 'max_pressure';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('standard_strokes_mm', '15, 30, 45, 60, 75, 100, 125, 150, 175, 200'),
  ('min_pressure_mpa', '0.06'),
  ('order_code_example', 'CJ2B16-200Z'),
  ('catalogue', 'SMC CJ2-Z, How to Order sida 74, data sida 75')
) as x(key, value)
where p.sku = 'SMC-CJ2B16'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);

-- seriens samlingsrad
update product_specs s set value = '6, 10, 16'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2' and s.key = 'bore_mm';

update product_specs s set value = '15–200 mm (standard); tillverkas upp till 400 mm'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2' and s.key = 'stroke_mm';

update product_specs s set value = '-10…+70 (utan givare), -10…+60 (med givare)'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2' and s.key = 'temp_range';

update product_specs s set value = '7'
from products p where s.product_id = p.id and p.sku = 'SMC-CJ2' and s.key = 'max_pressure';

insert into product_specs (product_id, key, value)
select p.id, x.key, x.value
from products p
cross join lateral (values
  ('order_code_example', 'CJ2B16-60Z'),
  ('catalogue', 'SMC CJ2-Z, How to Order sida 74, data sida 75')
) as x(key, value)
where p.sku = 'SMC-CJ2'
  and not exists (select 1 from product_specs y where y.product_id = p.id and y.key = x.key);

-- ø20 finns inte i CJ2 (katalogen är ø6, 10 och 16). Raden hänvisar till
-- ingenting och avaktiveras; ingen BOM, offert, relation eller
-- konkurrentkarta pekar på den (kontrollerat 2026-09-15).
update products set status = 'discontinued' where sku = 'SMC-CJ2B20' and status = 'active';


commit;

